function validate(input) {
  const [{ Listens = [], Friendship = [] }] = input;
  for (const [user, song, day] of Listens) {
    if (user === null || song === null || day === null) return 'Every listen needs a user_id, a song_id and a day.';
    if (!/^\d{4}-\d{2}-\d{2}$/.test(day)) return `Day ${day} is not a YYYY-MM-DD date.`;
  }
  const pairs = new Set();
  for (const [a, b] of Friendship) {
    if (a === null || b === null) return 'Every friendship needs two users.';
    if (!(a < b)) return `Friendship (${a}, ${b}) must have user1_id < user2_id.`;
    const key = `${a}:${b}`;
    if (pairs.has(key)) return `Friendship (${a}, ${b}) appears twice.`;
    pairs.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const Listens = [], Friendship = [];
  if (size === 'small') {
    const days = ['2021-03-15', '2021-03-16'];
    const songs = [10, 11, 12, 13, 14];
    // A shared playlist that a few users play on one day, sometimes missing a song.
    const day = days[pick(2)];
    const playlist = songs.filter(() => rand() < 0.7).slice(0, 4);
    const listeners = pick(4);
    for (let user = 1; user <= listeners; user++) {
      for (const song of playlist) if (rand() < 0.85) Listens.push([user, song, rand() < 0.85 ? day : days[pick(2)]]);
    }
    const extra = pick(4);
    for (let i = 0; i < extra; i++) {
      if (Listens.length && rand() < 0.4) Listens.push([...Listens[pick(Listens.length)]]);
      else Listens.push([1 + pick(5), songs[pick(songs.length)], days[pick(2)]]);
    }
    const seen = new Set();
    const friendCount = pick(4);
    for (let i = 0; i < friendCount; i++) {
      const a = 1 + pick(5), b = 1 + pick(5);
      if (a === b) continue;
      const pair = [Math.min(a, b), Math.max(a, b)];
      if (seen.has(pair.join(':'))) continue;
      seen.add(pair.join(':'));
      Friendship.push(pair);
    }
  } else {
    const days = ['2021-03-15', '2021-03-16', '2021-03-17', '2021-03-18'];
    const users = 120;
    for (let user = 1; user <= users; user++) {
      const first = pick(4), second = (first + 1 + pick(3)) % 4;
      for (const d of [first, second]) {
        const chosen = new Set();
        while (chosen.size < 6) chosen.add(1 + pick(25));
        for (const song of chosen) {
          Listens.push([user, song, days[d]]);
          if (rand() < 0.04) Listens.push([user, song, days[d]]);
        }
      }
    }
    const seen = new Set();
    while (Friendship.length < 600) {
      const a = 1 + pick(users), b = 1 + pick(users);
      if (a === b) continue;
      const pair = [Math.min(a, b), Math.max(a, b)];
      if (seen.has(pair.join(':'))) continue;
      seen.add(pair.join(':'));
      Friendship.push(pair);
    }
  }
  return [{ Listens, Friendship }];
}
